/// <reference types="next" />
/// <reference types="next/image-types/global" />
/// <reference path="./.next/types/routes.d.ts" />

// NOTE: This file should not be edited
// see https://nextjs.org/docs/app/api-reference/config/typescript for more information.

'use client';

import React, { useState } from 'react';
import { Form, Input, Button, Typography, Checkbox, Divider, Space, App } from 'antd';
import { LockOutlined, MailOutlined, GoogleOutlined } from '@ant-design/icons';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { loginWithEmail, loginWithGoogle } from '../actions';

const { Title, Text } = Typography;

export default function LoginPage() {
    const [loading, setLoading] = useState(false);
    const { message } = App.useApp();
    const router = useRouter();

    const onFinish = async (values: { email: string; password: string }) => {
        setLoading(true);
        const formData = new FormData();
        formData.append('email', values.email);
        formData.append('password', values.password);

        const result = await loginWithEmail(formData);
        if (result?.error) {
            message.error(result.error);
            setLoading(false);
        } else if (result?.success) {
            // refresh() clears Next.js router cache so the new session cookie
            // is picked up before navigating to the protected route
            router.refresh();
            router.push('/dashboard');
        }
    };

    const handleGoogleLogin = async () => {
        const result = await loginWithGoogle();
        if (result?.error) {
            message.error(result.error);
        }
    };


    return (
        <div
            style={{
                minHeight: '100vh',
                display: 'flex',
                background: '#f0f2f5',
            }}
        >
            {/* Left — Branding Panel */}
            <div
                style={{
                    flex: '0 0 480px',
                    background: 'linear-gradient(160deg, #0f172a 0%, #134e4a 60%, #0d9488 100%)',
                    display: 'flex',
                    flexDirection: 'column',
                    justifyContent: 'center',
                    padding: '64px 48px',
                    position: 'relative',
                    overflow: 'hidden',
                }}
                className="hidden lg:flex"
            >
                {/* Decorative circles */}
                <div
                    style={{
                        position: 'absolute',
                        width: 400,
                        height: 400,
                        borderRadius: '50%',
                        border: '1px solid rgba(255,255,255,0.06)',
                        top: -100,
                        right: -100,
                    }}
                />
                <div
                    style={{
                        position: 'absolute',
                        width: 300,
                        height: 300,
                        borderRadius: '50%',
                        border: '1px solid rgba(255,255,255,0.04)',
                        bottom: -50,
                        left: -80,
                    }}
                />

                <div style={{ position: 'relative', zIndex: 1 }}>
                    <div
                        style={{
                            width: 56,
                            height: 56,
                            borderRadius: 14,
                            background: 'rgba(255,255,255,0.1)',
                            backdropFilter: 'blur(8px)',
                            border: '1px solid rgba(255,255,255,0.15)',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            fontSize: 26,
                            fontWeight: 800,
                            color: '#5eead4',
                            marginBottom: 32,
                        }}
                    >
                        M
                    </div>
                    <h2 style={{ color: 'white', fontSize: 32, fontWeight: 800, margin: 0, lineHeight: 1.3 }}>
                        Quản lý phòng trọ
                        <br />
                        <span style={{ color: '#5eead4' }}>thông minh.</span>
                    </h2>
                    <p style={{ color: 'rgba(255,255,255,0.6)', fontSize: 15, marginTop: 16, lineHeight: 1.7, maxWidth: 360 }}>
                        Giảm 70% thời gian tạo hoá đơn. Quản lý điện nước, thu tiền, hợp đồng — tất cả trong một nền tảng duy nhất.
                    </p>

                    <div style={{ marginTop: 40, display: 'flex', gap: 32 }}>
                        {[
                            { num: '150+', label: 'Phòng quản lý' },
                            { num: '~0', label: 'Lỗi thu tiền' },
                            { num: '70%', label: 'Tiết kiệm thời gian' },
                        ].map((item, i) => (
                            <div key={i}>
                                <div style={{ color: '#5eead4', fontSize: 24, fontWeight: 800 }}>{item.num}</div>
                                <div style={{ color: 'rgba(255,255,255,0.5)', fontSize: 12, marginTop: 2 }}>{item.label}</div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Right — Login Form */}
            <div
                style={{
                    flex: 1,
                    display: 'flex',
                    flexDirection: 'column',
                    justifyContent: 'center',
                    alignItems: 'center',
                    padding: '48px 24px',
                }}
            >
                <div style={{ width: '100%', maxWidth: 400 }}>
                    {/* Mobile Logo */}
                    <div className="lg:hidden" style={{ textAlign: 'center', marginBottom: 32 }}>
                        <div
                            style={{
                                width: 48,
                                height: 48,
                                borderRadius: 12,
                                background: 'linear-gradient(135deg, #0d9488, #14b8a6)',
                                display: 'inline-flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                fontSize: 22,
                                fontWeight: 800,
                                color: 'white',
                                marginBottom: 12,
                            }}
                        >
                            M
                        </div>
                        <Title level={4} style={{ margin: 0 }}>MBP System</Title>
                    </div>

                    <Title level={3} style={{ margin: 0, fontWeight: 700 }}>
                        Đăng nhập
                    </Title>
                    <Text type="secondary" style={{ display: 'block', marginBottom: 32, marginTop: 4 }}>
                        Chào mừng trở lại! Hãy đăng nhập để tiếp tục.
                    </Text>

                    {/* Google Login */}
                    <Button
                        block
                        size="large"
                        icon={<GoogleOutlined />}
                        onClick={handleGoogleLogin}
                        style={{ height: 44, fontWeight: 500, marginBottom: 16 }}
                    >
                        Tiếp tục với Google
                    </Button>

                    <Divider style={{ margin: '16px 0', color: '#94a3b8', fontSize: 13 }}>
                        hoặc dùng Email
                    </Divider>

                    <Form
                        name="login"
                        initialValues={{ remember: true }}
                        onFinish={onFinish}
                        layout="vertical"
                        size="large"
                        requiredMark={false}
                    >
                        <Form.Item
                            name="email"
                            label={<span style={{ fontWeight: 500 }}>Email</span>}
                            rules={[
                                { required: true, message: 'Vui lòng nhập Email!' },
                                { type: 'email', message: 'Email không hợp lệ!' },
                            ]}
                        >
                            <Input
                                prefix={<MailOutlined style={{ color: '#94a3b8' }} />}
                                placeholder="admin@example.com"
                            />
                        </Form.Item>

                        <Form.Item
                            name="password"
                            label={<span style={{ fontWeight: 500 }}>Mật khẩu</span>}
                            rules={[{ required: true, message: 'Vui lòng nhập mật khẩu!' }]}
                        >
                            <Input.Password
                                prefix={<LockOutlined style={{ color: '#94a3b8' }} />}
                                placeholder="••••••••"
                            />
                        </Form.Item>

                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
                            <Form.Item name="remember" valuePropName="checked" noStyle>
                                <Checkbox>Ghi nhớ đăng nhập</Checkbox>
                            </Form.Item>
                            <Link href="#" style={{ color: '#0d9488', fontWeight: 500, fontSize: 13 }}>
                                Quên mật khẩu?
                            </Link>
                        </div>

                        <Form.Item>
                            <Button
                                type="primary"
                                htmlType="submit"
                                block
                                loading={loading}
                                style={{ height: 44, fontWeight: 600, fontSize: 15 }}
                            >
                                Đăng nhập
                            </Button>
                        </Form.Item>
                    </Form>

                    <Divider style={{ margin: '16px 0', color: '#94a3b8', fontSize: 13 }}>
                        Chưa có tài khoản?
                    </Divider>

                    <Link href="/register" style={{ display: 'block' }}>
                        <Button block size="large" style={{ height: 44, fontWeight: 600 }}>
                            Đăng ký tài khoản mới
                        </Button>
                    </Link>

                    <div style={{ textAlign: 'center', marginTop: 32, color: '#94a3b8', fontSize: 12 }}>
                        © 2025 MBP System. All rights reserved.
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import {
    Row, Col, Card, Button, Tag, Typography, Empty, message, Statistic, Space, Tooltip, Dropdown,
} from 'antd';
import {
    PlusOutlined, EditOutlined, DeleteOutlined, HomeOutlined,
    EnvironmentOutlined, MoreOutlined, EyeOutlined,
} from '@ant-design/icons';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import type { Building } from '@/types/database';
import { deleteBuilding } from './actions';
import dynamic from 'next/dynamic';
const BuildingFormModal = dynamic(() => import('./BuildingFormModal'), { ssr: false });
import ConfirmModal from '@/components/common/ConfirmModal';
import SearchInput from '@/components/common/SearchInput';

const { Text } = Typography;

interface BuildingsClientProps {
    initialBuildings: Building[];
    serverError?: string;
}

export default function BuildingsClient({ initialBuildings, serverError }: BuildingsClientProps) {
    const router = useRouter();
    const [buildings, setBuildings] = useState(initialBuildings);
    const [search, setSearch] = useState('');
    const [modalOpen, setModalOpen] = useState(false);
    const [editingBuilding, setEditingBuilding] = useState<Building | null>(null);
    const [deleteTarget, setDeleteTarget] = useState<Building | null>(null);
    const [deleting, setDeleting] = useState(false);

    if (serverError) {
        message.error(serverError);
    }

    const filtered = buildings.filter(
        (b) =>
            b.name.toLowerCase().includes(search.toLowerCase()) ||
            b.address?.toLowerCase().includes(search.toLowerCase())
    );

    const handleEdit = (building: Building) => {
        setEditingBuilding(building);
        setModalOpen(true);
    };

    const handleCreate = () => {
        setEditingBuilding(null);
        setModalOpen(true);
    };

    const handleDelete = async () => {
        if (!deleteTarget) return;
        setDeleting(true);
        const result = await deleteBuilding(deleteTarget.id);
        if (result.error) {
            message.error(result.error);
        } else {
            message.success('Đã xoá toà nhà thành công');
            setBuildings((prev) => prev.filter((b) => b.id !== deleteTarget.id));
        }
        setDeleting(false);
        setDeleteTarget(null);
    };

    const handleSuccess = () => {
        // Reload page to get fresh data from server
        window.location.reload();
    };

    const statusColor = (status: string) =>
        status === 'active' ? 'green' : 'default';

    const statusLabel = (status: string) =>
        status === 'active' ? 'Hoạt động' : 'Tạm ngưng';

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            {/* Toolbar */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
                <SearchInput
                    placeholder="Tìm toà nhà theo tên, địa chỉ..."
                    onSearch={setSearch}
                    style={{ maxWidth: 320 }}
                />
                <Button type="primary" icon={<PlusOutlined />} onClick={handleCreate}>
                    Thêm toà nhà
                </Button>
            </div>

            {/* Building cards grid */}
            {filtered.length === 0 ? (
                <Card style={{ borderRadius: 12 }}>
                    <Empty
                        description={search ? 'Không tìm thấy toà nhà phù hợp' : 'Chưa có toà nhà nào'}
                        image={Empty.PRESENTED_IMAGE_SIMPLE}
                    >
                        {!search && (
                            <Button type="primary" icon={<PlusOutlined />} onClick={handleCreate}>
                                Thêm toà nhà đầu tiên
                            </Button>
                        )}
                    </Empty>
                </Card>
            ) : (
                <Row gutter={[16, 16]}>
                    {filtered.map((building) => (
                        <Col xs={24} sm={12} lg={8} xl={6} key={building.id}>
                            <Card
                                hoverable
                                style={{ borderRadius: 12, height: '100%' }}
                                styles={{ body: { padding: '20px 20px 16px' } }}
                                actions={[
                                    <Tooltip title="Xem phòng" key="view">
                                        <Link href={`/buildings/${building.id}`} onClick={(e) => e.stopPropagation()}>
                                            <EyeOutlined />
                                        </Link>
                                    </Tooltip>,
                                    <Tooltip title="Chỉnh sửa" key="edit">
                                        <EditOutlined
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                handleEdit(building);
                                            }}
                                        />
                                    </Tooltip>,
                                    <Tooltip title="Xoá" key="delete">
                                        <DeleteOutlined
                                            style={{ color: '#ef4444' }}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                setDeleteTarget(building);
                                            }}
                                        />
                                    </Tooltip>,
                                ]}
                                onClick={() => router.push(`/buildings/${building.id}`)}
                            >
                                {/* Header */}
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 12 }}>
                                    <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
                                        <div
                                            style={{
                                                width: 40,
                                                height: 40,
                                                borderRadius: 10,
                                                background: 'linear-gradient(135deg, #0d9488, #14b8a6)',
                                                display: 'flex',
                                                alignItems: 'center',
                                                justifyContent: 'center',
                                                flexShrink: 0,
                                            }}
                                        >
                                            <HomeOutlined style={{ color: 'white', fontSize: 18 }} />
                                        </div>
                                        <div>
                                            <Text strong style={{ fontSize: 15 }}>{building.name}</Text>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: 4, marginTop: 2 }}>
                                                <EnvironmentOutlined style={{ fontSize: 11, color: '#94a3b8' }} />
                                                <Text type="secondary" style={{ fontSize: 12 }} ellipsis>
                                                    {building.address || 'Chưa cập nhật'}
                                                </Text>
                                            </div>
                                        </div>
                                    </div>
                                    <Tag color={statusColor(building.status)}>{statusLabel(building.status)}</Tag>
                                </div>

                                {/* Stats */}
                                <div
                                    style={{
                                        display: 'grid',
                                        gridTemplateColumns: '1fr 1fr 1fr',
                                        gap: 8,
                                        padding: '12px 0',
                                        borderTop: '1px solid #f0f0f0',
                                    }}
                                >
                                    <div style={{ textAlign: 'center' }}>
                                        <div style={{ fontSize: 20, fontWeight: 700, color: '#1e293b' }}>
                                            {building.room_count ?? 0}
                                        </div>
                                        <div style={{ fontSize: 11, color: '#94a3b8' }}>Tổng phòng</div>
                                    </div>
                                    <div style={{ textAlign: 'center' }}>
                                        <div style={{ fontSize: 20, fontWeight: 700, color: '#0d9488' }}>
                                            {building.occupied_count ?? 0}
                                        </div>
                                        <div style={{ fontSize: 11, color: '#94a3b8' }}>Đang thuê</div>
                                    </div>
                                    <div style={{ textAlign: 'center' }}>
                                        <div style={{ fontSize: 20, fontWeight: 700, color: '#3b82f6' }}>
                                            {building.vacant_count ?? 0}
                                        </div>
                                        <div style={{ fontSize: 11, color: '#94a3b8' }}>Trống</div>
                                    </div>
                                </div>

                                {/* Footer info */}
                                <div style={{ borderTop: '1px solid #f0f0f0', paddingTop: 8, marginTop: 4 }}>
                                    <Text type="secondary" style={{ fontSize: 12 }}>
                                        {building.num_floors} tầng
                                        {building.description && ` · ${building.description}`}
                                    </Text>
                                </div>
                            </Card>
                        </Col>
                    ))}
                </Row>
            )}

            {/* Form Modal */}
            <BuildingFormModal
                open={modalOpen}
                building={editingBuilding}
                onClose={() => {
                    setModalOpen(false);
                    setEditingBuilding(null);
                }}
                onSuccess={handleSuccess}
            />

            {/* Delete Confirm */}
            <ConfirmModal
                open={!!deleteTarget}
                title="Xoá toà nhà"
                description={`Bạn có chắc muốn xoá "${deleteTarget?.name}"? Tất cả phòng trong toà nhà cũng sẽ bị xoá. Hành động không thể hoàn tác.`}
                confirmText="Xoá toà nhà"
                loading={deleting}
                onConfirm={handleDelete}
                onCancel={() => setDeleteTarget(null)}
            />
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import {
    Card, Table, Button, Tag, Typography, Space, message, Breadcrumb, Statistic, Row, Col,
} from 'antd';
import {
    PlusOutlined, EditOutlined, DeleteOutlined, UploadOutlined,
    HomeOutlined, ArrowLeftOutlined, CheckCircleOutlined,
    ClockCircleOutlined, ToolOutlined, DollarOutlined, AppstoreOutlined
} from '@ant-design/icons';
import Link from 'next/link';
import { Tabs } from 'antd';
import type { Building, Room, RoomStatus, RoomType, ServicePrice } from '@/types/database';
import { deleteRoom } from './actions';
import RoomFormModal from './RoomFormModal';
import CsvImportModal from './CsvImportModal';
import ConfirmModal from '@/components/common/ConfirmModal';
import SearchInput from '@/components/common/SearchInput';
import ServicePricesTable from './ServicePricesTable';

const { Text, Title } = Typography;

const statusConfig: Record<RoomStatus, { label: string; color: string; icon: React.ReactNode }> = {
    vacant: { label: 'Trống', color: 'blue', icon: <CheckCircleOutlined /> },
    occupied: { label: 'Đang thuê', color: 'green', icon: <HomeOutlined /> },
    maintenance: { label: 'Sửa chữa', color: 'orange', icon: <ToolOutlined /> },
};

const roomTypeLabels: Record<RoomType, string> = {
    single: 'Đơn',
    double: 'Đôi',
    studio: 'Studio',
    other: 'Khác',
};

interface Props {
    building: Building;
    initialRooms: Room[];
    initialServicePrices: ServicePrice[];
}

export default function BuildingDetailClient({ building, initialRooms, initialServicePrices }: Props) {
    const [rooms, setRooms] = useState(initialRooms);
    const [search, setSearch] = useState('');
    const [modalOpen, setModalOpen] = useState(false);
    const [csvModalOpen, setCsvModalOpen] = useState(false);
    const [editingRoom, setEditingRoom] = useState<Room | null>(null);
    const [deleteTarget, setDeleteTarget] = useState<Room | null>(null);
    const [deleting, setDeleting] = useState(false);

    const filtered = rooms.filter(
        (r) =>
            r.name.toLowerCase().includes(search.toLowerCase()) ||
            r.notes?.toLowerCase().includes(search.toLowerCase())
    );

    const handleDelete = async () => {
        if (!deleteTarget) return;
        setDeleting(true);
        const result = await deleteRoom(deleteTarget.id, building.id);
        if (result.error) {
            message.error(result.error);
        } else {
            message.success('Đã xoá phòng thành công');
            setRooms((prev) => prev.filter((r) => r.id !== deleteTarget.id));
        }
        setDeleting(false);
        setDeleteTarget(null);
    };

    const handleSuccess = () => {
        window.location.reload();
    };

    // Stats
    const totalRooms = rooms.length;
    const occupied = rooms.filter((r) => r.status === 'occupied').length;
    const vacant = rooms.filter((r) => r.status === 'vacant').length;
    const maintenance = rooms.filter((r) => r.status === 'maintenance').length;

    const columns = [
        {
            title: 'Tên phòng',
            dataIndex: 'name',
            key: 'name',
            render: (name: string, record: Room) => (
                <Link href={`/rooms/${record.id}`} style={{ color: '#0d9488', fontWeight: 600 }}>
                    {name}
                </Link>
            ),
            sorter: (a: Room, b: Room) => a.name.localeCompare(b.name),
        },
        {
            title: 'Tầng',
            dataIndex: 'floor',
            key: 'floor',
            width: 80,
            align: 'center' as const,
            sorter: (a: Room, b: Room) => a.floor - b.floor,
        },
        {
            title: 'Loại',
            dataIndex: 'room_type',
            key: 'room_type',
            width: 100,
            render: (type: RoomType) => roomTypeLabels[type] || type,
        },
        {
            title: 'Diện tích (m²)',
            dataIndex: 'area_m2',
            key: 'area_m2',
            width: 120,
            align: 'right' as const,
            render: (val: number | null) => val ? `${val}` : '—',
        },
        {
            title: 'Giá thuê (đ)',
            dataIndex: 'default_rent',
            key: 'default_rent',
            width: 140,
            align: 'right' as const,
            render: (val: number) =>
                val ? new Intl.NumberFormat('vi-VN').format(val) : '—',
            sorter: (a: Room, b: Room) => a.default_rent - b.default_rent,
        },
        {
            title: 'Trạng thái',
            dataIndex: 'status',
            key: 'status',
            width: 120,
            filters: [
                { text: 'Trống', value: 'vacant' },
                { text: 'Đang thuê', value: 'occupied' },
                { text: 'Sửa chữa', value: 'maintenance' },
            ],
            onFilter: (value: unknown, record: Room) => record.status === value,
            render: (status: RoomStatus) => {
                const config = statusConfig[status];
                return (
                    <Tag color={config.color} icon={config.icon}>
                        {config.label}
                    </Tag>
                );
            },
        },
        {
            title: 'Ghi chú',
            dataIndex: 'notes',
            key: 'notes',
            ellipsis: true,
            render: (notes: string | null) => notes || <Text type="secondary">—</Text>,
        },
        {
            title: '',
            key: 'actions',
            width: 100,
            render: (_: unknown, record: Room) => (
                <Space size="small">
                    <Button
                        type="text"
                        size="small"
                        icon={<EditOutlined />}
                        onClick={() => {
                            setEditingRoom(record);
                            setModalOpen(true);
                        }}
                    />
                    <Button
                        type="text"
                        size="small"
                        danger
                        icon={<DeleteOutlined />}
                        onClick={() => setDeleteTarget(record)}
                    />
                </Space>
            ),
        },
    ];

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            {/* Breadcrumb */}
            <Breadcrumb
                items={[
                    { title: <Link href="/buildings">Toà nhà</Link> },
                    { title: building.name },
                ]}
            />

            {/* Header */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
                <div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <Link href="/buildings">
                            <Button type="text" icon={<ArrowLeftOutlined />} size="small" />
                        </Link>
                        <Title level={4} style={{ margin: 0, fontWeight: 700 }}>{building.name}</Title>
                        <Tag color={building.status === 'active' ? 'green' : 'default'}>
                            {building.status === 'active' ? 'Hoạt động' : 'Tạm ngưng'}
                        </Tag>
                    </div>
                    {building.address && (
                        <Text type="secondary" style={{ fontSize: 13, marginLeft: 40 }}>
                            {building.address}
                        </Text>
                    )}
                </div>
                <Space>
                    <Button icon={<UploadOutlined />} onClick={() => setCsvModalOpen(true)}>
                        Import CSV
                    </Button>
                    <Button
                        type="primary"
                        icon={<PlusOutlined />}
                        onClick={() => {
                            setEditingRoom(null);
                            setModalOpen(true);
                        }}
                    >
                        Thêm phòng
                    </Button>
                </Space>
            </div>

            {/* Stats Cards */}
            <Row gutter={[16, 16]}>
                {[
                    { title: 'Tổng phòng', value: totalRooms, color: '#1e293b' },
                    { title: 'Đang thuê', value: occupied, color: '#0d9488', suffix: `/ ${totalRooms}` },
                    { title: 'Trống', value: vacant, color: '#3b82f6' },
                    { title: 'Sửa chữa', value: maintenance, color: '#f59e0b' },
                ].map((stat, i) => (
                    <Col xs={12} sm={6} key={i}>
                        <Card style={{ borderRadius: 12 }} styles={{ body: { padding: '16px 20px' } }}>
                            <Statistic
                                title={<span style={{ fontSize: 12, color: '#94a3b8' }}>{stat.title}</span>}
                                value={stat.value}
                                suffix={stat.suffix}
                                valueStyle={{ color: stat.color, fontSize: 24, fontWeight: 700 }}
                            />
                        </Card>
                    </Col>
                ))}
            </Row>

            <Tabs
                defaultActiveKey="rooms"
                items={[
                    {
                        key: 'rooms',
                        label: <span style={{ fontWeight: 500 }}><AppstoreOutlined /> Danh sách phòng</span>,
                        children: (
                            <Card style={{ borderRadius: 12 }} styles={{ body: { padding: '16px 0' } }}>
                                <div style={{ padding: '0 16px 16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                    <Text strong style={{ fontSize: 15 }}>Danh sách phòng</Text>
                                    <SearchInput
                                        placeholder="Tìm phòng..."
                                        onSearch={setSearch}
                                    />
                                </div>
                                <Table
                                    columns={columns}
                                    dataSource={filtered}
                                    rowKey="id"
                                    pagination={filtered.length > 10 ? { pageSize: 10, showTotal: (t) => `Tổng ${t} phòng` } : false}
                                    size="middle"
                                    locale={{ emptyText: 'Chưa có phòng nào' }}
                                />
                            </Card>
                        )
                    },
                    {
                        key: 'services',
                        label: <span style={{ fontWeight: 500 }}><DollarOutlined /> Bảng giá dịch vụ</span>,
                        children: (
                            <Card style={{ borderRadius: 12 }} styles={{ body: { padding: '16px 0' } }}>
                                <ServicePricesTable buildingId={building.id} initialPrices={initialServicePrices} />
                            </Card>
                        )
                    }
                ]}
            />

            {/* Room Form Modal */}
            <RoomFormModal
                open={modalOpen}
                room={editingRoom}
                buildingId={building.id}
                numFloors={building.num_floors}
                onClose={() => {
                    setModalOpen(false);
                    setEditingRoom(null);
                }}
                onSuccess={handleSuccess}
            />

            {/* CSV Import Modal */}
            <CsvImportModal
                open={csvModalOpen}
                buildingId={building.id}
                onClose={() => setCsvModalOpen(false)}
                onSuccess={handleSuccess}
            />

            {/* Delete Confirm */}
            <ConfirmModal
                open={!!deleteTarget}
                title="Xoá phòng"
                description={`Bạn có chắc muốn xoá phòng "${deleteTarget?.name}"? Hành động không thể hoàn tác.`}
                confirmText="Xoá phòng"
                loading={deleting}
                onConfirm={handleDelete}
                onCancel={() => setDeleteTarget(null)}
            />
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { Modal, Upload, Button, Table, Typography, Alert, message, Space } from 'antd';
import { UploadOutlined, FileExcelOutlined, DownloadOutlined } from '@ant-design/icons';
import type { RoomFormData, RoomType, RoomStatus } from '@/types/database';
import { bulkImportRooms } from './actions';

const { Text } = Typography;

interface CsvImportModalProps {
    open: boolean;
    buildingId: string;
    onClose: () => void;
    onSuccess: () => void;
}

interface ParsedRow extends RoomFormData {
    key: string;
    _error?: string;
}

// Parse CSV text into rows
function parseCsv(text: string): ParsedRow[] {
    const lines = text.trim().split('\n');
    if (lines.length < 2) return []; // Need header + at least 1 row

    const header = lines[0].toLowerCase().split(',').map((h) => h.trim());

    return lines.slice(1).map((line, idx) => {
        const values = line.split(',').map((v) => v.trim());
        const row: Record<string, string> = {};
        header.forEach((h, i) => {
            row[h] = values[i] || '';
        });

        const validTypes: RoomType[] = ['single', 'double', 'studio', 'other'];
        const validStatuses: RoomStatus[] = ['vacant', 'occupied', 'maintenance'];

        const roomType = (row.room_type || row['loai_phong'] || 'single') as RoomType;
        const status = (row.status || row['trang_thai'] || 'vacant') as RoomStatus;

        const parsed: ParsedRow = {
            key: String(idx),
            name: row.name || row['ten_phong'] || '',
            floor: parseInt(row.floor || row['tang'] || '1', 10) || 1,
            area_m2: parseFloat(row.area_m2 || row['dien_tich'] || '0') || undefined,
            room_type: validTypes.includes(roomType) ? roomType : 'single',
            default_rent: parseInt(row.default_rent || row['gia_thue'] || '0', 10) || 0,
            status: validStatuses.includes(status) ? status : 'vacant',
            notes: row.notes || row['ghi_chu'] || '',
        };

        // Validate
        if (!parsed.name) {
            parsed._error = 'Thiếu tên phòng';
        }

        return parsed;
    });
}

const previewColumns = [
    { title: 'Tên phòng', dataIndex: 'name', key: 'name' },
    { title: 'Tầng', dataIndex: 'floor', key: 'floor', width: 70 },
    { title: 'Loại', dataIndex: 'room_type', key: 'room_type', width: 80 },
    {
        title: 'Diện tích',
        dataIndex: 'area_m2',
        key: 'area_m2',
        width: 90,
        render: (v: number | undefined) => v || '—',
    },
    {
        title: 'Giá thuê',
        dataIndex: 'default_rent',
        key: 'default_rent',
        width: 110,
        render: (v: number) => (v ? new Intl.NumberFormat('vi-VN').format(v) : '—'),
    },
    { title: 'Trạng thái', dataIndex: 'status', key: 'status', width: 100 },
    {
        title: 'Lỗi',
        dataIndex: '_error',
        key: '_error',
        width: 140,
        render: (err: string | undefined) =>
            err ? <Text type="danger" style={{ fontSize: 12 }}>{err}</Text> : null,
    },
];

const CSV_TEMPLATE = `name,floor,room_type,area_m2,default_rent,status,notes
P.101,1,single,20,3500000,vacant,
P.102,1,double,30,4500000,vacant,Có ban công
P.201,2,single,20,3500000,vacant,
P.202,2,studio,35,5000000,vacant,Có bếp riêng`;

export default function CsvImportModal({ open, buildingId, onClose, onSuccess }: CsvImportModalProps) {
    const [parsedRows, setParsedRows] = useState<ParsedRow[]>([]);
    const [importing, setImporting] = useState(false);
    const [fileSelected, setFileSelected] = useState(false);

    const handleFile = (file: File) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const text = e.target?.result as string;
            const rows = parseCsv(text);
            setParsedRows(rows);
            setFileSelected(true);
        };
        reader.readAsText(file);
        return false; // Prevention default upload
    };

    const handleImport = async () => {
        const valid = parsedRows.filter((r) => !r._error);
        if (valid.length === 0) {
            message.error('Không có dữ liệu hợp lệ để import');
            return;
        }

        setImporting(true);
        const result = await bulkImportRooms(
            buildingId,
            valid.map(({ key, _error, ...data }) => data)
        );

        if (result.error) {
            message.error(result.error);
        } else {
            message.success(`Import thành công ${result.count} phòng!`);
            handleReset();
            onClose();
            onSuccess();
        }
        setImporting(false);
    };

    const handleReset = () => {
        setParsedRows([]);
        setFileSelected(false);
    };

    const handleDownloadTemplate = () => {
        const blob = new Blob([CSV_TEMPLATE], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'template_import_phong.csv';
        a.click();
        URL.revokeObjectURL(url);
    };

    const errorCount = parsedRows.filter((r) => r._error).length;
    const validCount = parsedRows.length - errorCount;

    return (
        <Modal
            open={open}
            title={
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <FileExcelOutlined style={{ color: '#0d9488' }} />
                    <span style={{ fontWeight: 700, fontSize: 16 }}>Import phòng từ CSV</span>
                </div>
            }
            width={800}
            centered
            onCancel={() => {
                handleReset();
                onClose();
            }}
            footer={
                fileSelected
                    ? [
                        <Button key="reset" onClick={handleReset}>Chọn file khác</Button>,
                        <Button
                            key="import"
                            type="primary"
                            loading={importing}
                            onClick={handleImport}
                            disabled={validCount === 0}
                        >
                            Import {validCount} phòng
                        </Button>,
                    ]
                    : null
            }
        >
            {!fileSelected ? (
                <div style={{ textAlign: 'center', padding: '24px 0' }}>
                    <div style={{ marginBottom: 16 }}>
                        <Text type="secondary">
                            Upload file CSV chứa danh sách phòng. File cần có header row với các cột:
                        </Text>
                        <div style={{
                            marginTop: 8,
                            padding: '8px 12px',
                            background: '#f8fafc',
                            borderRadius: 6,
                            fontFamily: 'monospace',
                            fontSize: 12,
                            color: '#64748b',
                        }}>
                            name, floor, room_type, area_m2, default_rent, status, notes
                        </div>
                    </div>

                    <Space direction="vertical" size={12}>
                        <Upload
                            accept=".csv,.txt"
                            showUploadList={false}
                            beforeUpload={handleFile}
                        >
                            <Button icon={<UploadOutlined />} size="large" type="primary">
                                Chọn file CSV
                            </Button>
                        </Upload>

                        <Button
                            type="link"
                            icon={<DownloadOutlined />}
                            onClick={handleDownloadTemplate}
                            style={{ fontSize: 13 }}
                        >
                            Tải file mẫu (template)
                        </Button>
                    </Space>
                </div>
            ) : (
                <div>
                    {errorCount > 0 && (
                        <Alert
                            type="warning"
                            message={`${errorCount} dòng có lỗi sẽ bị bỏ qua khi import`}
                            style={{ marginBottom: 12 }}
                            showIcon
                        />
                    )}
                    <Alert
                        type="info"
                        message={`Tìm thấy ${parsedRows.length} dòng — ${validCount} hợp lệ`}
                        style={{ marginBottom: 12 }}
                        showIcon
                    />
                    <Table
                        columns={previewColumns}
                        dataSource={parsedRows}
                        size="small"
                        pagination={false}
                        scroll={{ y: 300 }}
                        rowClassName={(record) => (record._error ? 'ant-table-row-error' : '')}
                    />
                </div>
            )}
        </Modal>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Table, Input, InputNumber, Switch, Button, message, Popconfirm, Select, Space } from 'antd';
import { DeleteOutlined, SaveOutlined, PlusOutlined } from '@ant-design/icons';
import type { ServicePrice, ServicePriceFormData, ServiceType } from '@/types/database';
import { upsertServicePrices } from './actions';

interface Props {
    buildingId: string;
    initialPrices: ServicePrice[];
}

const defaultServices: { type: ServiceType; label: string; unit: string; is_metered: boolean }[] = [
    { type: 'electricity', label: 'Điện', unit: 'kWh', is_metered: true },
    { type: 'water', label: 'Nước', unit: 'm3', is_metered: true },
    { type: 'internet', label: 'Internet', unit: 'phòng/tháng', is_metered: false },
    { type: 'garbage', label: 'Rác', unit: 'phòng/tháng', is_metered: false },
    { type: 'parking', label: 'Gửi xe', unit: 'xe/tháng', is_metered: false },
];

export default function ServicePricesTable({ buildingId, initialPrices }: Props) {
    const [prices, setPrices] = useState<ServicePriceFormData[]>([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (initialPrices.length > 0) {
            setPrices(initialPrices.map(p => ({
                building_id: p.building_id,
                service_type: p.service_type,
                label: p.label,
                unit_price: p.unit_price,
                unit: p.unit,
                is_metered: p.is_metered
            })));
        } else {
            // Populate defaults if empty
            setPrices(defaultServices.map(ds => ({
                building_id: buildingId,
                service_type: ds.type,
                label: ds.label,
                unit_price: 0,
                unit: ds.unit,
                is_metered: ds.is_metered
            })));
        }
    }, [initialPrices, buildingId]);

    const handleChange = (index: number, key: keyof ServicePriceFormData, value: any) => {
        const newData = [...prices];
        newData[index] = { ...newData[index], [key]: value };
        setPrices(newData);
    };

    const handleAdd = () => {
        setPrices([
            ...prices,
            {
                building_id: buildingId,
                service_type: 'other',
                label: 'Dịch vụ khác',
                unit_price: 0,
                unit: '',
                is_metered: false
            }
        ]);
    };

    const handleDelete = (index: number) => {
        const newData = [...prices];
        newData.splice(index, 1);
        setPrices(newData);
    };

    const handleSave = async () => {
        setLoading(true);
        const result = await upsertServicePrices(buildingId, prices);
        if (result.error) {
            message.error(result.error);
        } else {
            message.success('Đã lưu cấu hình bảng giá');
        }
        setLoading(false);
    };

    const columns = [
        {
            title: 'Loại dịch vụ',
            dataIndex: 'service_type',
            width: 150,
            render: (val: string, record: ServicePriceFormData, index: number) => (
                <Select
                    value={val}
                    onChange={(v) => handleChange(index, 'service_type', v)}
                    style={{ width: '100%' }}
                    options={[
                        { value: 'electricity', label: 'Điện', disabled: prices.some((p, i) => i !== index && p.service_type === 'electricity') },
                        { value: 'water', label: 'Nước', disabled: prices.some((p, i) => i !== index && p.service_type === 'water') },
                        { value: 'internet', label: 'Internet', disabled: prices.some((p, i) => i !== index && p.service_type === 'internet') },
                        { value: 'garbage', label: 'Rác', disabled: prices.some((p, i) => i !== index && p.service_type === 'garbage') },
                        { value: 'parking', label: 'Gửi xe', disabled: prices.some((p, i) => i !== index && p.service_type === 'parking') },
                        { value: 'other', label: 'Khác' },
                    ]}
                />
            )
        },
        {
            title: 'Tên hiển thị',
            dataIndex: 'label',
            width: 200,
            render: (val: string, record: ServicePriceFormData, index: number) => (
                <Input value={val} onChange={(e) => handleChange(index, 'label', e.target.value)} />
            )
        },
        {
            title: 'Đơn giá (VND)',
            dataIndex: 'unit_price',
            width: 150,
            render: (val: number, record: ServicePriceFormData, index: number) => (
                <InputNumber
                    style={{ width: '100%' }}
                    value={val}
                    onChange={(v) => handleChange(index, 'unit_price', v || 0)}
                    formatter={(value) => `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
                    parser={(value) => value ? Number(value.replace(/\$\s?|(,*)/g, '')) as any : undefined}
                    min={0}
                />
            )
        },
        {
            title: 'Đơn vị tính',
            dataIndex: 'unit',
            width: 120,
            render: (val: string, record: ServicePriceFormData, index: number) => (
                <Input value={val} onChange={(e) => handleChange(index, 'unit', e.target.value)} placeholder="kWh, m3, tháng..." />
            )
        },
        {
            title: 'Ghi số công tơ',
            dataIndex: 'is_metered',
            width: 120,
            align: 'center' as const,
            render: (val: boolean, record: ServicePriceFormData, index: number) => (
                <Switch
                    checked={val}
                    onChange={(v) => handleChange(index, 'is_metered', v)}
                    disabled={record.service_type === 'electricity' || record.service_type === 'water'}
                />
            )
        },
        {
            title: '',
            key: 'action',
            width: 50,
            align: 'center' as const,
            render: (_: any, __: any, index: number) => (
                <Button type="text" danger icon={<DeleteOutlined />} onClick={() => handleDelete(index)} />
            )
        }
    ];

    return (
        <div style={{ padding: '0 16px 16px' }}>
            <Table
                dataSource={prices}
                columns={columns}
                rowKey={(r, idx) => idx?.toString() || ''}
                pagination={false}
                size="middle"
            />
            <div style={{ marginTop: 16, display: 'flex', justifyContent: 'space-between' }}>
                <Button type="dashed" onClick={handleAdd} icon={<PlusOutlined />}>
                    Thêm dịch vụ
                </Button>
                <Button type="primary" icon={<SaveOutlined />} onClick={handleSave} loading={loading}>
                    Lưu bảng giá
                </Button>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Modal, Form, Input, DatePicker, Select, InputNumber, message, Upload, Button } from 'antd';
import { UploadOutlined } from '@ant-design/icons';
import type { Contract, Room, Tenant, ContractFormData } from '@/types/database';
import { createContract, updateContract } from './actions';
import { createClient } from '@/lib/supabase/client';
import dayjs from 'dayjs';
import type { UploadFile } from 'antd/es/upload/interface';

interface Props {
    open: boolean;
    contract: Contract | null;
    rooms: Room[];
    tenants: Tenant[];
    onClose: () => void;
    onSuccess: () => void;
}

export default function ContractFormModal({ open, contract, rooms, tenants, onClose, onSuccess }: Props) {
    const [form] = Form.useForm();
    const [loading, setLoading] = useState(false);
    const [fileList, setFileList] = useState<UploadFile[]>([]);
    const [selectedBuildingId, setSelectedBuildingId] = useState<string | null>(null);
    const isEdit = !!contract;

    const buildings = Array.from(
        new Map(rooms.filter(r => r.building).map(r => [r.building!.id, r.building])).values()
    );

    useEffect(() => {
        if (open) {
            if (contract?.scan_url) {
                setFileList([
                    {
                        uid: '-1',
                        name: 'Contract_Scan.pdf',
                        status: 'done',
                        url: contract.scan_url,
                    },
                ]);
            } else {
                setFileList([]);
            }

            if (contract?.room_id) {
                const room = rooms.find(r => r.id === contract.room_id);
                if (room?.building?.id) {
                    setSelectedBuildingId(room.building.id);
                }
            } else {
                setSelectedBuildingId(null);
            }
        }
    }, [open, contract, rooms]);

    const handleRoomChange = (roomId: string) => {
        const room = rooms.find(r => r.id === roomId);
        if (room && !form.getFieldValue('rent_amount')) {
            form.setFieldsValue({ rent_amount: room.default_rent });
        }
    };

    const handleSubmit = async () => {
        const values = await form.validateFields();
        setLoading(true);

        let uploadedUrl = contract?.scan_url || undefined;

        // Upload new file to Supabase if exists
        if (fileList.length > 0 && fileList[0].originFileObj) {
            const supabase = createClient();
            const file = fileList[0].originFileObj;
            const fileExt = file.name.split('.').pop();
            const fileName = `${Date.now()}_${Math.random().toString(36).substring(7)}.${fileExt}`;

            const { error: uploadError } = await supabase.storage
                .from('contracts')
                .upload(fileName, file);

            if (uploadError) {
                message.error('Lỗi tải file lên: ' + uploadError.message);
                setLoading(false);
                return;
            }

            const { data } = supabase.storage.from('contracts').getPublicUrl(fileName);
            uploadedUrl = data.publicUrl;
        } else if (fileList.length === 0) {
            uploadedUrl = undefined;
        }

        const formData: ContractFormData & { scan_url?: string } = {
            room_id: values.room_id,
            tenant_id: values.tenant_id,
            rent_amount: values.rent_amount,
            deposit: values.deposit || 0,
            start_date: values.start_date.format('YYYY-MM-DD'),
            end_date: values.end_date ? values.end_date.format('YYYY-MM-DD') : undefined,
            status: values.status,
            notes: values.notes || undefined,
            scan_url: uploadedUrl,
        };

        const result = isEdit
            ? await updateContract(contract.id, formData)
            : await createContract(formData);

        if (result.error) {
            message.error(result.error);
        } else {
            message.success(isEdit ? 'Đã cập nhật hợp đồng' : 'Đã thêm hợp đồng mới');
            form.resetFields();
            setFileList([]);
            onClose();
            onSuccess();
        }

        setLoading(false);
    };

    return (
        <Modal
            title={isEdit ? 'Chỉnh sửa hợp đồng' : 'Thêm hợp đồng mới'}
            open={open}
            onOk={handleSubmit}
            onCancel={() => {
                form.resetFields();
                onClose();
            }}
            okText={isEdit ? 'Cập nhật' : 'Tạo mới'}
            cancelText="Huỷ"
            confirmLoading={loading}
            width={600}
            destroyOnClose
        >
            <Form
                form={form}
                layout="vertical"
                requiredMark={false}
                initialValues={
                    contract
                        ? {
                            room_id: contract.room_id,
                            tenant_id: contract.tenant_id,
                            rent_amount: contract.rent_amount,
                            deposit: contract.deposit,
                            start_date: dayjs(contract.start_date),
                            end_date: contract.end_date ? dayjs(contract.end_date) : null,
                            status: contract.status,
                            notes: contract.notes,
                        }
                        : {
                            status: 'active',
                            deposit: 0,
                        }
                }
                style={{ marginTop: 16 }}
            >
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
                    <Form.Item label="Tòa nhà">
                        <Select
                            placeholder="Chọn tòa nhà"
                            showSearch
                            optionFilterProp="children"
                            value={selectedBuildingId}
                            onChange={(value) => {
                                setSelectedBuildingId(value);
                                form.setFieldsValue({ room_id: undefined, rent_amount: undefined });
                            }}
                            options={buildings.map((b) => ({
                                value: b?.id,
                                label: b?.name,
                            }))}
                        />
                    </Form.Item>

                    <Form.Item
                        name="room_id"
                        label="Phòng thuê"
                        rules={[{ required: true, message: 'Vui lòng chọn phòng' }]}
                    >
                        <Select
                            placeholder="Chọn phòng"
                            showSearch
                            optionFilterProp="children"
                            onChange={handleRoomChange}
                            disabled={!selectedBuildingId}
                            options={rooms
                                .filter(r => r.building?.id === selectedBuildingId)
                                .map((r) => {
                                    const isOccupied = r.status === 'occupied' && (!isEdit || contract?.room_id !== r.id);
                                    return {
                                        value: r.id,
                                        label: `${r.name} ${isOccupied ? '(Đã thuê)' : ''}`,
                                        disabled: isOccupied,
                                    };
                                })}
                        />
                    </Form.Item>
                </div>

                <Form.Item
                    name="tenant_id"
                    label="Khách thuê đại diện"
                    rules={[{ required: true, message: 'Vui lòng chọn khách thuê' }]}
                >
                    <Select
                        placeholder="Chọn khách thuê"
                        showSearch
                        optionFilterProp="children"
                        options={tenants.map((t) => ({
                            value: t.id,
                            label: `${t.full_name} - ${t.phone || t.id_number || ''}`,
                        }))}
                    />
                </Form.Item>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
                    <Form.Item
                        name="rent_amount"
                        label="Giá thuê/tháng (VND)"
                        rules={[{ required: true, message: 'Vui lòng nhập giá thuê' }]}
                    >
                        <InputNumber
                            style={{ width: '100%' }}
                            formatter={(value) => `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
                            parser={(value) => value ? Number(value.replace(/\$\s?|(,*)/g, '')) as any : undefined}
                            min={0}
                        />
                    </Form.Item>

                    <Form.Item
                        name="deposit"
                        label="Tiền cọc (VND)"
                    >
                        <InputNumber
                            style={{ width: '100%' }}
                            formatter={(value) => `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
                            parser={(value) => value ? Number(value.replace(/\$\s?|(,*)/g, '')) as any : undefined}
                            min={0}
                        />
                    </Form.Item>
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 16 }}>
                    <Form.Item
                        name="start_date"
                        label="Ngày bắt đầu"
                        rules={[{ required: true, message: 'Chọn ngày bắt đầu' }]}
                    >
                        <DatePicker format="DD/MM/YYYY" style={{ width: '100%' }} />
                    </Form.Item>

                    <Form.Item
                        name="end_date"
                        label="Ngày kết thúc"
                    >
                        <DatePicker format="DD/MM/YYYY" style={{ width: '100%' }} placeholder="Vô thời hạn" />
                    </Form.Item>

                    <Form.Item
                        name="status"
                        label="Trạng thái"
                        rules={[{ required: true }]}
                    >
                        <Select
                            options={[
                                { value: 'active', label: 'Đang hiệu lực' },
                                { value: 'expired', label: 'Hết hạn' },
                                { value: 'terminated', label: 'Thanh lý' },
                            ]}
                        />
                    </Form.Item>
                </div>

                <Form.Item label="Bản scan Hợp đồng (PDF/Image)">
                    <Upload
                        listType="picture"
                        maxCount={1}
                        fileList={fileList}
                        beforeUpload={() => false}
                        onChange={(info) => {
                            setFileList(info.fileList);
                        }}
                    >
                        {fileList.length === 0 && (
                            <Button icon={<UploadOutlined />}>Tải file lên</Button>
                        )}
                    </Upload>
                </Form.Item>

                <Form.Item name="notes" label="Ghi chú">
                    <Input.TextArea rows={2} placeholder="Ghi chú thêm về hợp đồng..." />
                </Form.Item>
            </Form>
        </Modal>
    );
}

'use client';

import React, { useState } from 'react';
import {
    Card, Table, Button, Tag, Typography, Space, message, Select,
} from 'antd';
import {
    PlusOutlined, EditOutlined, DeleteOutlined, FileTextOutlined,
    StopOutlined, CheckCircleOutlined, SyncOutlined
} from '@ant-design/icons';
import type { Contract, Room, Tenant, ContractStatus } from '@/types/database';
import { deleteContract, updateContractStatus } from './actions';
import dynamic from 'next/dynamic';
const ContractFormModal = dynamic(() => import('./ContractFormModal'), { ssr: false });
import ConfirmModal from '@/components/common/ConfirmModal';
import dayjs from 'dayjs';

const { Text } = Typography;

interface Props {
    initialContracts: Contract[];
    rooms: Room[];
    tenants: Tenant[];
    serverError?: string | null;
}

export default function ContractsClient({ initialContracts, rooms, tenants, serverError }: Props) {
    const [contracts, setContracts] = useState(initialContracts);
    const [filterStatus, setFilterStatus] = useState<string>('all');
    const [modalOpen, setModalOpen] = useState(false);
    const [editingContract, setEditingContract] = useState<Contract | null>(null);
    const [deleteTarget, setDeleteTarget] = useState<Contract | null>(null);
    const [deleting, setDeleting] = useState(false);

    if (serverError) {
        message.error(serverError);
    }

    const filtered = contracts.filter((c) => {
        if (filterStatus === 'all') return true;
        return c.status === filterStatus;
    });

    const handleDelete = async () => {
        if (!deleteTarget) return;
        setDeleting(true);
        const result = await deleteContract(deleteTarget.id);
        if (result.error) {
            message.error(result.error);
        } else {
            message.success('Đã xoá hợp đồng');
            setContracts((prev) => prev.filter((c) => c.id !== deleteTarget.id));
        }
        setDeleting(false);
        setDeleteTarget(null);
    };

    const handleStatusChange = async (contract: Contract, newStatus: ContractStatus) => {
        const result = await updateContractStatus(contract.id, newStatus);
        if (result.error) {
            message.error(result.error);
        } else {
            message.success('Đã cập nhật trạng thái');
            // Cập nhật state local
            setContracts((prev) =>
                prev.map((c) => (c.id === contract.id ? { ...c, status: newStatus } : c))
            );
        }
    };

    const handleSuccess = () => {
        window.location.reload();
    };

    const formatCurrency = (value: number) => {
        return value.toLocaleString('vi-VN') + ' đ';
    };

    const getStatusConfig = (status: string) => {
        switch (status) {
            case 'active':
                return { color: 'green', text: 'Đang hiệu lực', icon: <CheckCircleOutlined /> };
            case 'expired':
                return { color: 'warning', text: 'Sắp/Đã hết hạn', icon: <SyncOutlined /> };
            case 'terminated':
                return { color: 'default', text: 'Đã thanh lý', icon: <StopOutlined /> };
            default:
                return { color: 'default', text: status, icon: null };
        }
    };

    const columns = [
        {
            title: 'Phòng / Khách thuê',
            key: 'info',
            render: (_: unknown, record: Contract) => (
                <div>
                    <Text strong style={{ fontSize: 14, color: '#0d9488' }}>
                        Phòng {record.room?.name}
                    </Text>
                    {record.room?.building && (
                        <Text type="secondary" style={{ fontSize: 12, marginLeft: 8 }}>
                            ({record.room.building.name})
                        </Text>
                    )}
                    <div style={{ marginTop: 4 }}>
                        <Text style={{ fontSize: 14 }}>{record.tenant?.full_name}</Text>
                        <Text type="secondary" style={{ fontSize: 12, marginLeft: 8 }}>
                            SĐT: {record.tenant?.phone || '—'}
                        </Text>
                    </div>
                </div>
            ),
        },
        {
            title: 'Giá thuê & Cọc',
            key: 'financials',
            render: (_: unknown, record: Contract) => (
                <div>
                    <div>Giá: <Text strong>{formatCurrency(record.rent_amount)}</Text></div>
                    <div style={{ fontSize: 12, color: '#64748b' }}>
                        Cọc: {formatCurrency(record.deposit)}
                    </div>
                </div>
            ),
        },
        {
            title: 'Thời hạn',
            key: 'period',
            render: (_: unknown, record: Contract) => (
                <div>
                    <div>Từ: <Text>{dayjs(record.start_date).format('DD/MM/YYYY')}</Text></div>
                    <div style={{ fontSize: 12, color: '#64748b' }}>
                        Đến: {record.end_date ? dayjs(record.end_date).format('DD/MM/YYYY') : 'Vô thời hạn'}
                    </div>
                </div>
            ),
        },
        {
            title: 'Trạng thái',
            key: 'status',
            render: (_: unknown, record: Contract) => {
                const config = getStatusConfig(record.status);
                return (
                    <Select
                        size="small"
                        value={record.status}
                        onChange={(val: ContractStatus) => handleStatusChange(record, val)}
                        style={{ width: 130 }}
                        options={[
                            { value: 'active', label: <Tag color="green">Đang hiệu lực</Tag> },
                            { value: 'expired', label: <Tag color="warning">Hết hạn</Tag> },
                            { value: 'terminated', label: <Tag color="default">Thanh lý</Tag> },
                        ]}
                    />
                );
            },
        },
        {
            title: 'Bản scan',
            dataIndex: 'scan_url',
            key: 'scan_url',
            align: 'center' as const,
            render: (url: string | null) =>
                url ? (
                    <Button
                        type="link"
                        icon={<FileTextOutlined />}
                        href={url}
                        target="_blank"
                    >
                        Xem
                    </Button>
                ) : (
                    <Text type="secondary">—</Text>
                ),
        },
        {
            title: '',
            key: 'actions',
            width: 90,
            align: 'right' as const,
            render: (_: unknown, record: Contract) => (
                <Space size="small">
                    <Button
                        type="text"
                        size="small"
                        icon={<EditOutlined />}
                        onClick={() => {
                            setEditingContract(record);
                            setModalOpen(true);
                        }}
                    />
                    <Button
                        type="text"
                        size="small"
                        danger
                        icon={<DeleteOutlined />}
                        onClick={() => setDeleteTarget(record)}
                    />
                </Space>
            ),
        },
    ];

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            {/* Toolbar */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
                <Space>
                    <Select
                        value={filterStatus}
                        onChange={setFilterStatus}
                        style={{ width: 150 }}
                        options={[
                            { value: 'all', label: 'Tất cả trạng thái' },
                            { value: 'active', label: 'Đang hiệu lực' },
                            { value: 'expired', label: 'Hết hạn' },
                            { value: 'terminated', label: 'Đã thanh lý' },
                        ]}
                    />
                </Space>
                <Button
                    type="primary"
                    icon={<PlusOutlined />}
                    onClick={() => {
                        setEditingContract(null);
                        setModalOpen(true);
                    }}
                >
                    Tạo hợp đồng
                </Button>
            </div>

            {/* Stats */}
            <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
                {[
                    { label: 'Tổng', value: contracts.length, color: '#1e293b' },
                    { label: 'Đang hiệu lực', value: contracts.filter((c) => c.status === 'active').length, color: '#0d9488' },
                    { label: 'Sắp hết hạn', value: contracts.filter((c) => c.status === 'expired').length, color: '#f59e0b' },
                ].map((stat) => (
                    <Card
                        key={stat.label}
                        styles={{ body: { padding: '12px 20px', textAlign: 'center' } }}
                        style={{ borderRadius: 12, minWidth: 120 }}
                    >
                        <div style={{ fontSize: 22, fontWeight: 700, color: stat.color }}>{stat.value}</div>
                        <div style={{ fontSize: 12, color: '#94a3b8' }}>{stat.label}</div>
                    </Card>
                ))}
            </div>

            {/* Table */}
            <Card style={{ borderRadius: 12 }} styles={{ body: { padding: '16px 0' } }}>
                <Table
                    columns={columns}
                    dataSource={filtered}
                    rowKey="id"
                    pagination={filtered.length > 10 ? { pageSize: 10 } : false}
                    size="middle"
                    locale={{ emptyText: 'Chưa có hợp đồng nào' }}
                />
            </Card>

            {/* Form Modal */}
            <ContractFormModal
                open={modalOpen}
                contract={editingContract}
                rooms={rooms}
                tenants={tenants}
                onClose={() => {
                    setModalOpen(false);
                    setEditingContract(null);
                }}
                onSuccess={handleSuccess}
            />

            {/* Delete Confirm */}
            <ConfirmModal
                open={!!deleteTarget}
                title="Xoá hợp đồng"
                description={`Bạn có chắc muốn xoá hợp đồng của phòng "${deleteTarget?.room?.name}"? Mọi thông tin liên quan sẽ bị xoá.`}
                confirmText="Xoá"
                loading={deleting}
                onConfirm={handleDelete}
                onCancel={() => setDeleteTarget(null)}
            />
        </div>
    );
}

'use server';

import { createClient } from '@/lib/supabase/server';

export async function getDashboardStats() {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return null;

    const { data: profile } = await supabase
        .from('user_profiles')
        .select('org_id, full_name, role')
        .eq('id', user.id)
        .single();

    if (!profile?.org_id) return null;

    // Get buildings count
    const { count: buildingCount } = await supabase
        .from('buildings')
        .select('*', { count: 'exact', head: true })
        .eq('org_id', profile.org_id);

    // Get all rooms for this org
    const { data: buildings } = await supabase
        .from('buildings')
        .select('id')
        .eq('org_id', profile.org_id);

    const buildingIds = buildings?.map(b => b.id) || [];

    let roomStats = { total: 0, occupied: 0, vacant: 0, maintenance: 0 };

    if (buildingIds.length > 0) {
        const { data: rooms } = await supabase
            .from('rooms')
            .select('status')
            .in('building_id', buildingIds);

        rooms?.forEach(r => {
            roomStats.total++;
            if (r.status === 'occupied') roomStats.occupied++;
            if (r.status === 'vacant') roomStats.vacant++;
            if (r.status === 'maintenance') roomStats.maintenance++;
        });
    }

    // Financial Stats
    const currentMonth = new Date().toISOString().slice(0, 7); // YYYY-MM
    let totalRevenue = 0;
    let totalDebt = 0;
    let totalCollectedThisMonth = 0;

    // Generate last 6 months list
    const last6Months = Array.from({ length: 6 }).map((_, i) => {
        const d = new Date();
        d.setMonth(d.getMonth() - i);
        return d.toISOString().slice(0, 7);
    }).reverse();

    const monthlyRevenueMap: Record<string, { month: string, revenue: number, collected: number }> = {};
    last6Months.forEach(m => {
        monthlyRevenueMap[m] = { month: m, revenue: 0, collected: 0 };
    });

    if (buildingIds.length > 0) {
        const { data: invoices } = await supabase
            .from('invoices')
            .select('month, status, total_amount, paid_amount')
            .in('building_id', buildingIds)
            .in('month', last6Months);

        invoices?.forEach(inv => {
            if (inv.status !== 'paid') {
                totalDebt += (Number(inv.total_amount) - Number(inv.paid_amount));
            }
            if (inv.month === currentMonth) {
                totalRevenue += Number(inv.total_amount);
                totalCollectedThisMonth += Number(inv.paid_amount);
            }
            if (monthlyRevenueMap[inv.month]) {
                monthlyRevenueMap[inv.month].revenue += Number(inv.total_amount);
                monthlyRevenueMap[inv.month].collected += Number(inv.paid_amount);
            }
        });
    }

    const monthlyRevenue = Object.values(monthlyRevenueMap);

    return {
        fullName: profile.full_name || 'Admin',
        role: profile.role,
        buildingCount: buildingCount || 0,
        roomStats,
        financials: {
            totalRevenue,
            totalCollectedThisMonth,
            totalDebt,
            monthlyRevenue
        }
    };
}

'use client';

import React, { useState, useEffect } from 'react';
import { Modal, Form, Input, Select, Button, Upload, message, Typography } from 'antd';
import { UploadOutlined } from '@ant-design/icons';
import type { UploadFile } from 'antd/es/upload/interface';
import { createClient } from '@/lib/supabase/client';
import type { Incident, IncidentFormData, Building, Room } from '@/types/database';
import { createIncident, updateIncident } from './actions';

const { TextArea } = Input;
const { Text } = Typography;

interface IncidentFormModalProps {
    visible: boolean;
    onClose: () => void;
    incident?: Incident;
    buildings: Building[];
    userId?: string;
}

export default function IncidentFormModal({ visible, onClose, incident, buildings, userId }: IncidentFormModalProps) {
    const [form] = Form.useForm<IncidentFormData>();
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [rooms, setRooms] = useState<Room[]>([]);
    const [fileList, setFileList] = useState<UploadFile[]>([]);
    const [selectedBuildingId, setSelectedBuildingId] = useState<string | undefined>();

    const supabase = createClient();

    useEffect(() => {
        if (visible) {
            if (incident) {
                form.setFieldsValue({
                    building_id: incident.building_id,
                    room_id: incident.room_id,
                    title: incident.title,
                    description: incident.description || '',
                    priority: incident.priority,
                    status: incident.status,
                    reporter_type: incident.reporter_type,
                    admin_notes: incident.admin_notes || '',
                });
                setSelectedBuildingId(incident.building_id);
                fetchRooms(incident.building_id);

                // Load existing images into fileList
                if (incident.image_urls && incident.image_urls.length > 0) {
                    setFileList(
                        incident.image_urls.map((url, index) => ({
                            uid: `-${index}`,
                            name: `image-${index}.jpg`,
                            status: 'done',
                            url: url,
                        }))
                    );
                } else {
                    setFileList([]);
                }
            } else {
                form.resetFields();
                // Default values for new incident
                form.setFieldsValue({
                    status: 'open',
                    priority: 'medium',
                    reporter_type: 'tenant', // Default to tenant for now
                });
                setFileList([]);
                setRooms([]);
                setSelectedBuildingId(undefined);
            }
        }
    }, [visible, incident, form]);

    const fetchRooms = async (buildingId: string) => {
        const { data } = await supabase
            .from('rooms')
            .select('*')
            .eq('building_id', buildingId)
            .order('name');

        if (data) {
            setRooms(data as Room[]);
        }
    };

    const handleBuildingChange = (value: string) => {
        setSelectedBuildingId(value);
        form.setFieldValue('room_id', undefined);
        fetchRooms(value);
    };

    const handleUploadChange = ({ fileList: newFileList }: { fileList: UploadFile[] }) => {
        setFileList(newFileList);
    };

    const uploadImages = async (): Promise<string[]> => {
        const uploadedUrls: string[] = [];

        // Loop through all files
        for (const file of fileList) {
            // Already uploaded files have a url property
            if (file.url) {
                uploadedUrls.push(file.url);
                continue;
            }

            if (file.originFileObj) {
                const fileExt = file.name.split('.').pop();
                const fileName = `incident_${Date.now()}_${Math.random().toString(36).substring(7)}.${fileExt}`;
                const filePath = `incidents/${fileName}`; // Reusing contracts bucket under 'incidents' folder

                // Using contracts bucket because it's already configured with public read access
                const { error: uploadError } = await supabase.storage
                    .from('contracts')
                    .upload(filePath, file.originFileObj);

                if (uploadError) {
                    console.error('Error uploading image:', uploadError);
                    throw new Error(`Không thể tải ảnh lên: ${uploadError.message}`);
                }

                const { data } = supabase.storage.from('contracts').getPublicUrl(filePath);
                if (data?.publicUrl) {
                    uploadedUrls.push(data.publicUrl);
                }
            }
        }

        return uploadedUrls;
    };

    const handleFinish = async (values: IncidentFormData) => {
        setIsSubmitting(true);
        try {
            // 1. Upload new images if any
            let imageUrls: string[] = [];
            try {
                imageUrls = await uploadImages();
            } catch (error: unknown) {
                if (error instanceof Error) {
                    message.error(error.message);
                } else {
                    message.error('Lỗi upload ảnh');
                }
                setIsSubmitting(false);
                return;
            }

            // 2. Prepare payload
            const payload: IncidentFormData = {
                ...values,
                image_urls: imageUrls.length > 0 ? imageUrls : undefined,
            };

            // 3. Submit
            let result;
            if (incident) {
                result = await updateIncident(incident.id, payload);
            } else {
                result = await createIncident(payload);
            }

            if (result.error) {
                message.error(result.error);
            } else {
                message.success(incident ? 'Cập nhật thành công!' : 'Đã báo cáo sự cố thành công!');
                onClose();
            }
        } catch (err: unknown) {
            if (err instanceof Error) {
                message.error('Lỗi hệ thống: ' + err.message);
            } else {
                message.error('Lỗi hệ thống không xác định');
            }
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <Modal
            title={incident ? "Cập nhật sự cố" : "Báo cáo sự cố mới"}
            open={visible}
            onCancel={onClose}
            footer={null}
            width={700}
            destroyOnClose
        >
            <Form
                form={form}
                layout="vertical"
                onFinish={handleFinish}
                className="mt-4"
            >
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-4">
                    <Form.Item
                        name="building_id"
                        label="Tòa nhà"
                        rules={[{ required: true, message: 'Vui lòng chọn tòa nhà!' }]}
                    >
                        <Select
                            placeholder="Chọn tòa nhà"
                            onChange={handleBuildingChange}
                        >
                            {buildings.map(b => (
                                <Select.Option key={b.id} value={b.id}>{b.name}</Select.Option>
                            ))}
                        </Select>
                    </Form.Item>

                    <Form.Item
                        name="room_id"
                        label="Phòng (Không bắt buộc)"
                    >
                        <Select
                            placeholder={selectedBuildingId ? "Chọn phòng (Nếu sự cố trong phòng)" : "Vui lòng chọn Tòa nhà trước"}
                            disabled={!selectedBuildingId}
                            allowClear
                        >
                            {rooms.map(r => (
                                <Select.Option key={r.id} value={r.id}>
                                    {r.name}
                                </Select.Option>
                            ))}
                        </Select>
                    </Form.Item>
                </div>

                <Form.Item
                    name="title"
                    label="Tiêu đề sự cố"
                    rules={[{ required: true, message: 'Vui lòng nhập tiêu đề ngắn gọn!' }]}
                >
                    <Input placeholder="Ví dụ: Vòi nước bồn rửa mặt bị rò rỉ" />
                </Form.Item>

                <Form.Item
                    name="description"
                    label="Mô tả chi tiết"
                >
                    <TextArea
                        rows={4}
                        placeholder="Mô tả rō hơn về tình trạng, vị trí cụ thể, thời gian phát hiện..."
                    />
                </Form.Item>

                <Form.Item label="Hình ảnh đính kèm (Tối đa 3 ảnh)">
                    <Upload
                        listType="picture-card"
                        fileList={fileList}
                        onChange={handleUploadChange}
                        beforeUpload={() => false} // Prevent automatic upload
                        maxCount={3}
                        accept="image/*"
                    >
                        {fileList.length >= 3 ? null : (
                            <div>
                                <UploadOutlined />
                                <div style={{ marginTop: 8 }}>Tải ảnh</div>
                            </div>
                        )}
                    </Upload>
                </Form.Item>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-x-4 p-4 bg-gray-50 rounded-lg mb-4">
                    <Form.Item
                        name="priority"
                        label="Mức độ"
                        rules={[{ required: true }]}
                        className="mb-0"
                    >
                        <Select>
                            <Select.Option value="low">Thấp</Select.Option>
                            <Select.Option value="medium">Trung bình</Select.Option>
                            <Select.Option value="high">Nghiêm trọng</Select.Option>
                        </Select>
                    </Form.Item>

                    <Form.Item
