'use server';

import { createClient } from '@/lib/supabase/server';

// Helper: get current user's org_id
async function getOrgId() {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return null;

    const { data: profile } = await supabase
        .from('user_profiles')
        .select('org_id')
        .eq('id', user.id)
        .single();

    return profile?.org_id || null;
}

export async function getInvoices(filters?: { month?: string; building_id?: string; status?: string }) {
    const supabase = await createClient();

    let query = supabase
        .from('invoices')
        .select('*, room:rooms(name), building:buildings(name), tenant:tenants(full_name)')
        .order('created_at', { ascending: false });

    if (filters?.month) query = query.eq('month', filters.month);
    if (filters?.building_id && filters.building_id !== 'all') query = query.eq('building_id', filters.building_id);
    if (filters?.status && filters.status !== 'all') query = query.eq('status', filters.status);

    const { data, error } = await query;
    if (error) return { data: null, error: error.message };
    return { data, error: null };
}

export async function getInvoiceById(id: string) {
    const supabase = await createClient();

    const { data: invoice, error: invoiceError } = await supabase
        .from('invoices')
        .select('*, room:rooms(name), building:buildings(name, address), tenant:tenants(full_name, phone)')
        .eq('id', id)
        .single();

    if (invoiceError) return { data: null, error: invoiceError.message };

    const { data: items, error: itemsError } = await supabase
        .from('invoice_items')
        .select('*')
        .eq('invoice_id', id)
        .order('created_at', { ascending: true });

    if (itemsError) return { data: null, error: itemsError.message };

    return { data: { ...invoice, items }, error: null };
}

export async function generateInvoices(buildingId: string, month: string) {
    const supabase = await createClient();
    const orgId = await getOrgId();
    if (!orgId) return { error: 'Không tìm thấy tổ chức. Vui lòng đăng nhập lại.' };

    // 1. Lấy tất cả hợp đồng đang hiệu lực trong toà nhà
    const { data: contracts, error: contractsError } = await supabase
        .from('contracts')
        .select('*, room:rooms!inner(id, building_id, name)')
        .eq('status', 'active')
        .eq('rooms.building_id', buildingId);

    if (contractsError) return { error: `Lỗi lấy hợp đồng: ${contractsError.message}` };
    if (!contracts || contracts.length === 0) return { error: 'Không có hợp đồng nào đang hoạt động trong toà nhà này.' };

    // 2. Lấy bảng giá dịch vụ cho toà nhà
    const { data: prices, error: pricesError } = await supabase
        .from('service_prices')
        .select('*')
        .eq('building_id', buildingId);

    if (pricesError) return { error: `Lỗi lấy bảng giá dịch vụ: ${pricesError.message}` };

    // 3. Lấy chỉ số đồng hồ điện/nước cho tháng này
    const roomIds = contracts.map(c => c.room_id);
    const { data: meters, error: metersError } = await supabase
        .from('meter_records')
        .select('*')
        .eq('period', month)
        .in('room_id', roomIds);

    if (metersError) return { error: `Lỗi lấy chỉ số đồng hồ: ${metersError.message}` };

    let generatedCount = 0;

    // Process each contract
    for (const contract of contracts) {
        // Kiểm tra xem phòng này đã có hoá đơn của tháng chưa
        const { data: existing } = await supabase
            .from('invoices')
            .select('id')
            .eq('room_id', contract.room_id)
            .eq('month', month)
            .single();

        if (existing) continue; // Bỏ qua nếu đã tạo

        // a. Tạo bản ghi invoice
        const date = new Date();
        date.setDate(date.getDate() + 5); // Tự động set hạn thanh toán là 5 ngày sau
        const dueDate = date.toISOString().split('T')[0];

        const { data: invoice, error: invoiceError } = await supabase
            .from('invoices')
            .insert({
                org_id: orgId,
                building_id: buildingId,
                room_id: contract.room_id,
                contract_id: contract.id,
                tenant_id: contract.tenant_id,
                month: month,
                title: `Hoá đơn tháng ${month} - Phòng ${contract.room.name}`,
                due_date: dueDate,
            })
            .select()
            .single();

        if (invoiceError || !invoice) continue;

        const invoiceItems: any[] = [];

        // b. Thêm mục Tiền phòng
        invoiceItems.push({
            invoice_id: invoice.id,
            type: 'rent',
            description: `Tiền thuê phòng tháng ${month}`,
            quantity: 1,
            unit_price: contract.rent_amount,
            amount: contract.rent_amount
        });

        // c. Thêm các mục dịch vụ tính theo đồng hồ (Điện, Nước)
        const meteredPrices = prices.filter(p => p.is_metered);
        for (const price of meteredPrices) {
            const meter = meters.find(m => m.room_id === contract.room_id && m.service_type === price.service_type);
            if (meter) {
                invoiceItems.push({
                    invoice_id: invoice.id,
                    type: price.service_type,
                    description: `${price.label} (${meter.old_reading} - ${meter.new_reading})`,
                    quantity: meter.usage,
                    unit_price: price.unit_price,
                    amount: meter.usage * price.unit_price,
                    reference_id: meter.id
                });
            }
        }

        // d. Thêm các mục dịch vụ cố định (Rác, Internet, Wifi)
        const fixedPrices = prices.filter(p => !p.is_metered);
        for (const price of fixedPrices) {
            invoiceItems.push({
                invoice_id: invoice.id,
                type: 'service',
                description: price.label,
                quantity: 1, // Thông thường tính trên phòng
                unit_price: price.unit_price,
                amount: price.unit_price
            });
        }

        // Lưu toàn bộ chi tiết hoá đơn
        if (invoiceItems.length > 0) {
            await supabase.from('invoice_items').insert(invoiceItems);
        }

        generatedCount++;
    }

    if (generatedCount === 0) {
        return { success: true, message: 'Tất cả các phòng đang hoạt động đều đã có hoá đơn cho tháng này.' };
    }

    return {
        success: true,
        message: `Đã tạo thành công hoá đơn cho ${generatedCount} phòng.`
    };
}

export async function payInvoice(id: string, amount: number) {
    const supabase = await createClient();

    // Lấy số tiền đã thanh toán hiện tại
    const { data: invoice, error: fetchError } = await supabase
        .from('invoices')
        .select('paid_amount, total_amount')
        .eq('id', id)
        .single();

    if (fetchError || !invoice) return { error: 'Không tìm thấy hoá đơn' };

    const newPaidAmount = Number(invoice.paid_amount) + Number(amount);

    // Lưu ý: Trigger CSDL sẽ tự động tính toán lại trường 'status' dựa trên paid_amount và total_amount
    const { error: updateError } = await supabase
        .from('invoices')
        .update({ paid_amount: newPaidAmount })
        .eq('id', id);

    if (updateError) return { error: updateError.message };
    return { success: true };
}

export async function deleteInvoice(id: string) {
    const supabase = await createClient();
    const { error } = await supabase.from('invoices').delete().eq('id', id);
    if (error) return { error: error.message };
    return { success: true };
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { Card, Table, Select, DatePicker, Button, InputNumber, Typography, message, Input, Tag } from 'antd';
import { SaveOutlined, ReloadOutlined } from '@ant-design/icons';
import dayjs, { Dayjs } from 'dayjs';
import { getMeterRecords, upsertMeterRecords } from './actions';

const { Title, Text } = Typography;

interface MeterRow {
    room_id: string;
    room_name: string;
    floor: number;
    status: string;
    electricity_old: number;
    electricity_new: number;
    electricity_usage: number;
    water_old: number;
    water_new: number;
    water_usage: number;
    id?: string;
    notes?: string;
}

interface Props {
    buildings: { id: string, name: string }[];
}

export default function MetersClient({ buildings }: Props) {
    const [buildingId, setBuildingId] = useState<string | null>(buildings[0]?.id || null);
    const [month, setMonth] = useState<Dayjs>(dayjs().startOf('month'));
    const [data, setData] = useState<MeterRow[]>([]);
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);

    const loadData = useCallback(async () => {
        if (!buildingId) return;
        setLoading(true);
        const monthStr = month.format('YYYY-MM-01');
        const res = await getMeterRecords(buildingId, monthStr);
        if (res.error) {
            message.error(res.error);
        } else {
            setData(res.data);
        }
        setLoading(false);
    }, [buildingId, month]);

    useEffect(() => {
        loadData();
    }, [loadData]);

    const handleChange = (index: number, field: keyof MeterRow, val: any) => {
        const newData = [...data];
        const row = { ...newData[index], [field]: val };

        if (field === 'electricity_old' || field === 'electricity_new') {
            const usage = (row.electricity_new || 0) - (row.electricity_old || 0);
            row.electricity_usage = usage > 0 ? usage : 0;
        }
        if (field === 'water_old' || field === 'water_new') {
            const usage = (row.water_new || 0) - (row.water_old || 0);
            row.water_usage = usage > 0 ? usage : 0;
        }

        newData[index] = row;
        setData(newData);
    };

    const handleSave = async () => {
        setSaving(true);
        const monthStr = month.format('YYYY-MM-01');
        const res = await upsertMeterRecords(monthStr, data);
        if (res.error) {
            message.error('Lưu thất bại: ' + res.error);
        } else {
            message.success('Đã lưu chỉ số thành công');
            loadData(); // refresh to get new IDs
        }
        setSaving(false);
    };

    const columns = [
        {
            title: 'Phòng',
            dataIndex: 'room_name',
            key: 'room_name',
            width: 120,
            render: (name: string, record: MeterRow) => (
                <div>
                    <Text strong>{name}</Text>
                    <br />
                    {record.status === 'occupied' ? <Tag color="green">Đang thuê</Tag> : <Tag color="default">Trống</Tag>}
                </div>
            )
        },
        {
            title: 'Chỉ số Điện',
            key: 'electricity',
            children: [
                {
                    title: 'Số cũ',
                    dataIndex: 'electricity_old',
                    width: 100,
                    render: (val: number, _: MeterRow, idx: number) => (
                        <InputNumber value={val} min={0} onChange={v => handleChange(idx, 'electricity_old', v || 0)} style={{ width: '100%' }} />
                    )
                },
                {
                    title: 'Số mới',
                    dataIndex: 'electricity_new',
                    width: 100,
                    render: (val: number, _: MeterRow, idx: number) => (
                        <InputNumber value={val} min={0} onChange={v => handleChange(idx, 'electricity_new', v || 0)} style={{ width: '100%' }} />
                    )
                },
                {
                    title: 'Tiêu thụ',
                    dataIndex: 'electricity_usage',
                    width: 90,
                    render: (val: number) => <Text strong type="danger">{val}</Text>
                }
            ]
        },
        {
            title: 'Chỉ số Nước',
            key: 'water',
            children: [
                {
                    title: 'Số cũ',
                    dataIndex: 'water_old',
                    width: 100,
                    render: (val: number, _: MeterRow, idx: number) => (
                        <InputNumber value={val} min={0} onChange={v => handleChange(idx, 'water_old', v || 0)} style={{ width: '100%' }} />
                    )
                },
                {
                    title: 'Số mới',
                    dataIndex: 'water_new',
                    width: 100,
                    render: (val: number, _: MeterRow, idx: number) => (
                        <InputNumber value={val} min={0} onChange={v => handleChange(idx, 'water_new', v || 0)} style={{ width: '100%' }} />
                    )
                },
                {
                    title: 'Tiêu thụ',
                    dataIndex: 'water_usage',
                    width: 90,
                    render: (val: number) => <Text strong style={{ color: '#0d9488' }}>{val}</Text>
                }
            ]
        },
        {
            title: 'Ghi chú',
            dataIndex: 'notes',
            key: 'notes',
            render: (val: string, _: MeterRow, idx: number) => (
                <Input value={val} placeholder="Ghi chú..." onChange={e => handleChange(idx, 'notes', e.target.value)} />
            )
        }
    ];

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            <Card style={{ borderRadius: 12 }}>
                <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap', alignItems: 'center', justifyContent: 'space-between' }}>
                    <div style={{ display: 'flex', gap: 16, alignItems: 'center' }}>
                        <Select
                            value={buildingId}
                            onChange={setBuildingId}
                            style={{ width: 200 }}
                            placeholder="Chọn toà nhà"
                            options={buildings.map(b => ({ value: b.id, label: b.name }))}
                        />
                        <DatePicker picker="month" value={month} onChange={(d) => d && setMonth(d.startOf('month'))} format="MM / YYYY" />
                        <Button icon={<ReloadOutlined />} onClick={loadData}>Tải thông tin</Button>
                    </div>

                    <Button type="primary" size="large" icon={<SaveOutlined />} onClick={handleSave} loading={saving}>
                        Lưu chỉ số Điện Nước
                    </Button>
                </div>
            </Card>

            <Table
                bordered
                dataSource={data}
                columns={columns as any}
                rowKey="room_id"
                loading={loading}
                pagination={false}
                size="middle"
                scroll={{ x: 800 }}
                rowClassName={(r) => r.status === 'vacant' ? 'opacity-50 grayscale bg-slate-50' : ''}
                locale={{ emptyText: 'Tòa nhà này hiện chưa có phòng nào.' }}
            />
        </div>
    );
}

'use server';

import { createClient } from '@/lib/supabase/server';
import { revalidatePath } from 'next/cache';

export async function getBuildingsForMeters() {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { data: [], error: 'Not authenticated' };

    const { data: profile } = await supabase
        .from('user_profiles')
        .select('org_id')
        .eq('id', user.id)
        .single();

    if (!profile?.org_id) return { data: [], error: 'Không tìm thấy tổ chức' };

    const { data, error } = await supabase
        .from('buildings')
        .select('id, name')
        .eq('org_id', profile.org_id)
        .eq('status', 'active');

    return { data: data || [], error: error?.message };
}

export async function getMeterRecords(buildingId: string, monthStr: string) {
    const supabase = await createClient();

    // 1. Fetch Rooms
    const { data: rooms } = await supabase
        .from('rooms')
        .select('id, name, status, floor')
        .eq('building_id', buildingId)
        .order('floor')
        .order('name');

    if (!rooms) return { data: [], error: 'Không thể tải phòng' };

    // 2. Lấy danh sách record tháng hiện tại (monthStr)
    const { data: currentRecords } = await supabase
        .from('meter_records')
        .select('*')
        .eq('record_month', monthStr);

    // 3. Tính tháng trước (ví dụ 2026-02-01 -> 2026-01-01)
    const dateObj = new Date(monthStr);
    dateObj.setMonth(dateObj.getMonth() - 1);
    const prevMonthStr = dateObj.toISOString().split('T')[0];

    const { data: prevRecords } = await supabase
        .from('meter_records')
        .select('*')
        .eq('record_month', prevMonthStr);

    const prevMap = Object.fromEntries((prevRecords || []).map(r => [r.room_id, r]));
    const currentMap = Object.fromEntries((currentRecords || []).map(r => [r.room_id, r]));

    // 4. Merge data
    const data = rooms.map(room => {
        const cur = currentMap[room.id];
        const prev = prevMap[room.id];
        return {
            room_id: room.id,
            room_name: room.name,
            floor: room.floor,
            status: room.status,
            electricity_old: cur?.electricity_old ?? prev?.electricity_new ?? 0,
            electricity_new: cur?.electricity_new ?? 0,
            electricity_usage: cur?.electricity_usage ?? 0,
            water_old: cur?.water_old ?? prev?.water_new ?? 0,
            water_new: cur?.water_new ?? 0,
            water_usage: cur?.water_usage ?? 0,
            id: cur?.id,
            notes: cur?.notes || '',
        };
    });

    return { data, error: null };
}

export async function upsertMeterRecords(monthStr: string, records: any[]) {
    const supabase = await createClient();

    const insertData = records.map(r => {
        // Only get exactly the fields needed by the database schema
        const item: any = {
            room_id: r.room_id,
            record_month: monthStr,
            electricity_old: r.electricity_old,
            electricity_new: r.electricity_new,
            electricity_usage: r.electricity_usage,
            water_old: r.water_old,
            water_new: r.water_new,
            water_usage: r.water_usage,
            notes: r.notes || null,
        };
        if (r.id) item.id = r.id; // required for upsert to know which record to update
        return item;
    });

    if (insertData.length > 0) {
        // Chú ý: trong file DB có defined ON CONFLICT
        const { error } = await supabase
            .from('meter_records')
            .upsert(insertData, { onConflict: 'room_id, record_month' });

        if (error) return { error: error.message };
    }

    revalidatePath('/meters');
    revalidatePath('/dashboard');
    return { success: true };
}

